import { ThumbsDown, ThumbsUp } from '@gntik-ai/icons';
import { Button, Field, FieldLabel, HStack, Stack, Text, Textarea } from '@gntik-ai/ui';
import { useId, useState } from 'react';

export interface ArticleFeedbackValue {
  helpful: boolean;
  comment?: string;
}

export interface ArticleFeedbackProps {
  onFeedback?: (value: ArticleFeedbackValue) => void;
}

/** "Was this helpful?" with Yes / No; No asks what was missing. Status changes are announced. */
export function ArticleFeedback({ onFeedback }: ArticleFeedbackProps) {
  const [answer, setAnswer] = useState<'yes' | 'no' | 'sent' | null>(null);
  const [comment, setComment] = useState('');
  const id = useId();

  const answerYes = () => {
    setAnswer('sent');
    onFeedback?.({ helpful: true });
  };
  const send = () => {
    setAnswer('sent');
    onFeedback?.({ helpful: false, comment: comment.trim() || undefined });
  };

  return (
    <section aria-labelledby={`${id}-title`} className="rounded-xl border border-border bg-card p-4">
      <h2 id={`${id}-title`} className="text-[14px] font-semibold text-foreground">
        Was this helpful?
      </h2>
      <div aria-live="polite">
        {answer === 'sent' ? (
          <Text variant="supporting" tone="muted" className="mt-1">
            Thanks for your feedback.
          </Text>
        ) : answer === 'no' ? (
          <form
            className="mt-3"
            onSubmit={(e) => {
              e.preventDefault();
              send();
            }}
          >
            <Stack gap={3}>
              <Field>
                <FieldLabel>What was missing?</FieldLabel>
                <Textarea rows={3} value={comment} onValueChange={setComment} placeholder="Optional" />
              </Field>
              <HStack gap={2}>
                <Button type="submit" size="sm">
                  Send feedback
                </Button>
                <Button variant="ghost" size="sm" onClick={() => setAnswer(null)}>
                  Cancel
                </Button>
              </HStack>
            </Stack>
          </form>
        ) : (
          <HStack gap={2} className="mt-3">
            <Button variant="secondary" size="sm" icon={ThumbsUp} onClick={answerYes}>
              Yes
            </Button>
            <Button variant="secondary" size="sm" icon={ThumbsDown} onClick={() => setAnswer('no')}>
              No
            </Button>
          </HStack>
        )}
      </div>
    </section>
  );
}

import { InlineCallout } from '@gntik-ai/blocks';
import { ArrowLeft, ArrowRight } from '@gntik-ai/icons';
import { Badge, Blockquote, CodeBlock, DocsLayout, HStack, Link, Logo, NavList, Stack, Text, ThemeSwitcher, Timestamp, type NavGroup, type OutlineItem } from '@gntik-ai/ui';
import type { ReactNode } from 'react';
import { ArticleFeedback, type ArticleFeedbackValue } from './ArticleFeedback';
import { articleNext, articlePrev, articleToc, docsNav, verifyCode, type ArticleLink } from './data';

export interface DocsArticleProps {
  brand: ReactNode;
  nav: NavGroup[];
  currentHref: string;
  eyebrow: string;
  title: string;
  lead: ReactNode;
  updatedAt: string;
  /** Table of contents; ids must match the headings of `children`. */
  toc: OutlineItem[];
  /** Article body; defaults to the sample “Verify webhook signatures” guide. */
  children: ReactNode;
  prev: ArticleLink | null;
  next: ArticleLink | null;
  onFeedback: (value: ArticleFeedbackValue) => void;
}

const P = 'text-[14px] leading-7 text-muted-foreground';
const H2 = 'mt-10 mb-3 scroll-mt-6 text-[18px] font-semibold tracking-tight text-foreground';
const H3 = 'mt-6 mb-2 scroll-mt-6 text-[15px] font-semibold text-foreground';

function SampleBody() {
  return (
    <>
      <h2 id="how-it-works" className={H2}>
        How signing works
      </h2>
      <p className={P}>
        Every delivery carries a <code className="rounded-sm bg-secondary px-1 py-0.5 font-mono text-[0.92em] text-foreground">Signature</code> header: a
        timestamp and an HMAC-SHA256 of the timestamp and the raw body, keyed with the endpoint secret.
      </p>
      <h2 id="verify" className={H2}>
        Verify a signature
      </h2>
      <p className={P}>Compute the same HMAC on your side and compare it in constant time. Use the raw body, before any JSON parsing.</p>
      <h3 id="verify-node" className={H3}>
        Node.js example
      </h3>
      <CodeBlock code={verifyCode} language="ts" filename="verify.ts" showLineNumbers />
      <h2 id="replay" className={H2}>
        Reject replayed events
      </h2>
      <p className={P}>Refuse deliveries whose timestamp is more than five minutes old, and store the ids of the events you processed.</p>
      <Blockquote source="Security review" sourceDetail="Platform team" className="my-5">
        A valid signature proves who sent the event, not when. Always check the timestamp too.
      </Blockquote>
      <h2 id="rotate" className={H2}>
        Rotate the secret
      </h2>
      <p className={P}>Rolling a secret keeps the old one valid for 24 hours, so you can deploy the new value without dropping deliveries.</p>
      <InlineCallout className="mt-4" tone="info" title="Tip" description="Store the secret in an environment variable, never in the repository." />
    </>
  );
}

/** Documentation article on DocsLayout: nav, scroll-spy Outline, code, quote, prev/next and feedback. */
export default function DocsArticlePage(props: Partial<DocsArticleProps>) {
  const {
    brand = <Logo size={22} wordmark />,
    nav = docsNav,
    currentHref = '/docs/webhooks',
    eyebrow = 'Guides · Webhooks',
    title = 'Verify webhook signatures',
    lead = 'Check that each delivery comes from us and has not been replayed before you act on it.',
    updatedAt = '2026-09-21',
    toc = articleToc,
    children = <SampleBody />,
    prev = articlePrev,
    next = articleNext,
    onFeedback,
  } = props;
  return (
    <DocsLayout
      fullScreen
      header={
        <>
          {brand}
          <Badge tone="neutral" size="sm">
            Docs
          </Badge>
          <ThemeSwitcher size="sm" className="ms-auto" />
        </>
      }
      nav={<NavList label="Documentation" groups={nav} currentHref={currentHref} />}
      toc={toc}
      footer={
        <Stack gap={6}>
          <ArticleFeedback onFeedback={onFeedback} />
          {(prev || next) && (
            <nav aria-label="Previous and next articles">
              <HStack justify="between" gap={4} className="text-[13px]">
                {prev ? (
                  <Link href={prev.href} className="inline-flex items-center gap-1.5">
                    <ArrowLeft size={14} aria-hidden /> <span className="sr-only">Previous: </span>
                    {prev.label}
                  </Link>
                ) : (
                  <span />
                )}
                {next && (
                  <Link href={next.href} className="inline-flex items-center gap-1.5">
                    <span className="sr-only">Next: </span>
                    {next.label} <ArrowRight size={14} aria-hidden />
                  </Link>
                )}
              </HStack>
            </nav>
          )}
        </Stack>
      }
    >
      <p className="font-mono text-[11px] tracking-[0.18em] text-primary-text uppercase">{eyebrow}</p>
      <h1 className="mt-2 text-[28px] font-bold tracking-[-0.02em] text-foreground">{title}</h1>
      <p className={`mt-3 ${P}`}>{lead}</p>
      <Text variant="caption" tone="muted" className="mt-2">
        Updated <Timestamp value={updatedAt} format="absolute" tooltip={false} dateOptions={{ dateStyle: 'medium' }} />
      </Text>
      {children}
    </DocsLayout>
  );
}

import { BookOpen, CreditCard, LifeBuoy, Plug, Rocket, Shield } from '@gntik-ai/icons';
import type { NavGroup, OutlineItem } from '@gntik-ai/ui';

export interface ArticleLink {
  label: string;
  href: string;
}

export const docsNav: NavGroup[] = [
  {
    label: 'Get started',
    items: [
      { label: 'Introduction', href: '/docs', icon: BookOpen },
      { label: 'Deploy a project', href: '/docs/deploy', icon: Rocket },
    ],
  },
  {
    label: 'Guides',
    items: [
      { label: 'Webhooks', href: '/docs/webhooks', icon: Plug },
      { label: 'Access control', href: '/docs/access', icon: Shield },
      { label: 'Billing', href: '/docs/billing', icon: CreditCard },
      { label: 'Support', href: '/docs/support', icon: LifeBuoy },
    ],
  },
];

export const articleToc: OutlineItem[] = [
  { id: 'how-it-works', label: 'How signing works' },
  { id: 'verify', label: 'Verify a signature' },
  { id: 'verify-node', label: 'Node.js example', level: 3 },
  { id: 'replay', label: 'Reject replayed events' },
  { id: 'rotate', label: 'Rotate the secret' },
];

export const verifyCode = `import { createHmac, timingSafeEqual } from 'node:crypto';

export function verify(payload: string, header: string, secret: string) {
  const [timestamp, signature] = header.split(',');
  const expected = createHmac('sha256', secret)
    .update(\`\${timestamp}.\${payload}\`)
    .digest('hex');
  return timingSafeEqual(Buffer.from(expected), Buffer.from(signature ?? ''));
}`;

export const articlePrev: ArticleLink = { label: 'Create a webhook', href: '/docs/webhooks/create' };
export const articleNext: ArticleLink = { label: 'Retry failed deliveries', href: '/docs/webhooks/retries' };
